class Solution:
    def findBlackPixel(self, picture: List[List[str]], target: int) -> int:
        m, n = len(picture), len(picture[0])
        ans = 0
        for r in range(m):
            for c in range(n):
                if picture[r][c] != 'B':
                    continue
                if sum(picture[r][j] == 'B' for j in range(n)) != target:
                    continue
                if sum(picture[i][c] == 'B' for i in range(m)) != target:
                    continue
                ok = True
                for i in range(m):
                    if picture[i][c] == 'B' and picture[i] != picture[r]:
                        ok = False
                        break
                if ok:
                    ans += 1
        return ans

