public:
    int findBlackPixel(vector<vector<char>>& picture, int target) {
        int m = picture.size(), n = picture[0].size(), ans = 0;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (picture[r][c] != 'B') continue;
                int rc = 0, cc = 0;
                for (int j = 0; j < n; j++) rc += picture[r][j] == 'B';
                for (int i = 0; i < m; i++) cc += picture[i][c] == 'B';
                if (rc != target || cc != target) continue;
                bool ok = true;
                for (int i = 0; i < m && ok; i++)
                    if (picture[i][c] == 'B' && picture[i] != picture[r]) ok = false;
                if (ok) ans++;
            }
        }
        return ans;
    }
};

