    def findBlackPixel(self, picture: List[List[str]], target: int) -> int:
        m, n = len(picture), len(picture[0])
        rows = [''.join(row) for row in picture]
        sig_count = Counter(rows)
        col_rows = defaultdict(list)
        for i in range(m):
            for j in range(n):
                if picture[i][j] == 'B':
                    col_rows[j].append(i)
        ans = 0
        for c, idxs in col_rows.items():
            if len(idxs) != target:
                continue
            first = rows[idxs[0]]
            if sig_count[first] >= target and all(rows[i] == first for i in idxs):
                ans += target
        return ans

