class Solution {
public:
    int findBlackPixel(vector<vector<char>>& picture, int target) {
        int m = picture.size(), n = picture[0].size();
        vector<string> rows(m);
        unordered_map<string,int> sigCount;
        for (int i = 0; i < m; i++) {
            rows[i] = string(picture[i].begin(), picture[i].end());
            sigCount[rows[i]]++;
        }
        vector<vector<int>> colRows(n);
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (picture[i][j] == 'B') colRows[j].push_back(i);
        int ans = 0;
        for (auto& [c, idxs] : colRows) {
            if ((int)idxs.size() != target) continue;
            const string& first = rows[idxs[0]];
            bool same = true;
            for (int i : idxs) if (rows[i] != first) { same = false; break; }
            if (same && sigCount[first] >= target) ans += target;
        }
        return ans;
    }
};

