class Solution {
    public int findBlackPixel(char[][] picture, int target) {
        int m = picture.length, n = picture[0].length;
        String[] rows = new String[m];
        Map<String, Integer> sigCount = new HashMap<>();
        for (int i = 0; i < m; i++) {
            rows[i] = new String(picture[i]);
            sigCount.merge(rows[i], 1, Integer::sum);
        }
        List<List<Integer>> colRows = new ArrayList<>();
        for (int j = 0; j < n; j++) colRows.add(new ArrayList<>());
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (picture[i][j] == 'B') colRows.get(j).add(i);
        int ans = 0;
        for (List<Integer> idxs : colRows) {
            if (idxs.size() != target) continue;
            String first = rows[idxs.get(0)];
            boolean same = true;
            for (int i : idxs) if (!rows[i].equals(first)) { same = false; break; }
            if (same && sigCount.get(first) >= target) ans += target;
        }
        return ans;
    }
}

