var findBlackPixel = function(picture, target) {
    const m = picture.length, n = picture[0].length;
    const rows = picture.map(r => r.join(''));
    const sigCount = {};
    for (const s of rows) sigCount[s] = (sigCount[s] || 0) + 1;
    const colRows = Array.from({length: n}, () => []);
    for (let i = 0; i < m; i++)
        for (let j = 0; j < n; j++)
            if (picture[i][j] === 'B') colRows[j].push(i);
    let ans = 0;
    for (const idxs of colRows) {
        if (idxs.length !== target) continue;
        const first = rows[idxs[0]];
        const same = idxs.every(i => rows[i] === first);
        if (same && sigCount[first] >= target) ans += target;
    }
    return ans;
};
